using System;using System.IO;using UnityEngine;using UnityEditor;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
namespace CityForge.Editor{[InitializeOnLoad]public static class MeadowNativeValidation{
const string W="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/work/meadow-native/",O="/Users/joelinstrum/Documents/Codex/2026-10-09/pl/outputs/";static double due;static int stage;static Camera camera;static Quaternion rotation;static Vector3 position;static float size;static bool ortho;
static MeadowNativeValidation(){EditorApplication.update+=Tick;}static void Tick(){if(EditorApplication.isCompiling||!EditorApplication.isPlaying)return;try{if(File.Exists(W+"views")){File.Delete(W+"views");camera=GameObject.Find("Meadow presentation camera").GetComponent<Camera>();rotation=camera.transform.rotation;position=camera.transform.position;size=camera.orthographicSize;ortho=camera.orthographic;stage=0;View();due=EditorApplication.timeSinceStartup+4;}if(due>0&&EditorApplication.timeSinceStartup>due){Capture();stage++;if(stage<4){View();due=EditorApplication.timeSinceStartup+4;}else{camera.orthographic=ortho;camera.orthographicSize=size;camera.transform.SetPositionAndRotation(position,rotation);camera.ResetProjectionMatrix();due=0;}}}catch(Exception e){due=0;File.WriteAllText(O+"MeadowNative_ViewError.txt",e.ToString());}}
static void View(){camera.farClipPlane=2400;if(stage<3){camera.orthographic=true;camera.orthographicSize=new[]{61.955f,247.82f,991.28f}[stage];camera.transform.rotation=rotation;camera.transform.position=new Vector3(133,8,130)-camera.transform.forward*110;}else{camera.orthographic=false;camera.fieldOfView=55;camera.transform.rotation=Quaternion.Euler(30,45,0);camera.transform.position=new Vector3(133,8,130)-camera.transform.forward*125;}camera.ResetProjectionMatrix();}
static void Capture(){var rt=new RenderTexture(1920,1080,24);rt.Create();var previous=RenderTexture.active;try{RenderPipeline.SubmitRenderRequest(camera,new UniversalRenderPipeline.SingleCameraRequest{destination=rt});RenderTexture.active=rt;var image=new Texture2D(1920,1080,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,1920,1080),0,0);image.Apply();File.WriteAllBytes(O+"MeadowNative_"+new[]{"Zoom1","Zoom3","Zoom5","Perspective"}[stage]+".png",image.EncodeToPNG());UnityEngine.Object.DestroyImmediate(image);}finally{RenderTexture.active=previous;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}}
